function CountUp({value,suffix=''}:{value:number;suffix?:string}){const ref=useRef<HTMLElement>(null);const[display,setDisplay]=useState(0);useEffect(()=>{const el=ref.current;if(!el)return;const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const run=()=>{if(reduce){setDisplay(value);return}let frame=0;const total=44;const tick=()=>{frame+=1;const progress=1-Math.pow(1-frame/total,3);setDisplay(Math.round(value*progress));if(frame<total)requestAnimationFrame(tick)};tick()};const observer=new IntersectionObserver(entries=>{if(entries[0]?.isIntersecting){run();observer.disconnect()}},{threshold:.35});observer.observe(el);return()=>observer.disconnect()},[value]);return <strong ref={ref}>{display}{suffix}</strong>}
