function Hero(){const router=useRouter();const{enquire}=useSite();const[slide,setSlide]=useState(0);const[paused,setPaused]=useState(false);const[interacting,setInteracting]=useState(false);const[q,setQ]=useState('');const[type,setType]=useState('All homes');const slides=[{image:'villa',line:<>A new home.<span className="heading-break"> </span>A whole new <em>beginning.</em></>,tag:'Space to grow. A place to belong.'},{image:'living-room',line:<>Find a home that<span className="heading-break"> </span>feels like <em>you.</em></>,tag:'Thoughtful spaces. Everyday possibilities.'},{image:'apartment-green',line:<>Your city.<span className="heading-break"> </span>Your next <em>chapter.</em></>,tag:'Discover your place in Bengaluru.'}];useEffect(()=>{if(paused||interacting||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const id=setInterval(()=>setSlide(s=>(s+1)%3),8000);return()=>clearInterval(id)},[paused,interacting]);return <><section className="hero" aria-label="Featured home inspiration" onMouseEnter={()=>{if(window.matchMedia('(max-width: 600px)').matches)setPaused(true)}} onFocusCapture={()=>{if(window.matchMedia('(max-width: 600px)').matches)setPaused(true);else setInteracting(true)}} onBlurCapture={e=>{if(!e.currentTarget.contains(e.relatedTarget))setInteracting(false)}}><div>{slides.map((s,i)=><div className={`hero-image ${slide===i?'active':''}`} key={s.image} aria-hidden={slide!==i}><img src={img(s.image)} alt="Illustrative contemporary residential architecture" fetchPriority={i===0?'high':'auto'}/></div>)}</div><div className="wrap hero-content"><div className="eyebrow">Bengaluru homes. Personal guidance.</div><h1 key={slide} className="reveal">{slides[slide].line}</h1><p>Find the right property, in the right neighbourhood,<br className="desktop-break"/> with a partner who puts you first.</p><form className="search-bar" onSubmit={e=>{e.preventDefault();router.push(`/properties?q=${encodeURIComponent(q)}${type==='All homes'?'':`&type=${type}`}`)}}><div className="search-field"><MapPin size={19}/><input aria-label="Search location or project" value={q} onChange={e=>setQ(e.target.value)} placeholder="Search a locality or project in Bengaluru"/></div><Drop label="Home type" value={type} onChange={setType} options={['All homes',...propertyTypes]}/><button className="btn primary">Search homes <Search size={17}/></button></form><div className="hero-actions"><Link href="/properties" className="btn lime">Explore homes <ArrowUpRight size={16}/></Link><button className="btn advisor-call" onClick={()=>enquire('Help me find my home')}><Phone size={17}/>Talk to an advisor</button></div><div className="popular"><span>POPULAR SEARCHES</span>{['Bagalur','Thanisandra','Devanahalli'].map(t=><Link key={t} href={`/properties?q=${encodeURIComponent(t)}`}>{t}</Link>)}<Link href="/properties?status=Ready%20to%20move">Ready to move</Link></div></div><div className="wrap hero-bottom"><div className="slide-info">{slides[slide].tag}<br/><span style={{opacity:.7}}>Photograph for visual inspiration</span></div><div className="slide-controls"><span className="slide-index">0{slide+1} / 03</span><button onClick={()=>setSlide((slide+2)%3)} aria-label="Previous hero slide"><ChevronLeft size={17}/></button><button onClick={()=>setSlide((slide+1)%3)} aria-label="Next hero slide"><ChevronRight size={17}/></button></div></div></section><div className="wrap quick-ribbon"><span><MapPin size={17}/> Bengaluru, through and through</span><span><Compass size={17}/> Shortlist to possession</span><span><Handshake size={17}/> One dedicated property partner</span><span><House size={17}/> Apartments · Villas · Plots</span></div></>}
