function FeaturedByAaramv(){const[index,setIndex]=useState(0);const viewport=useRef<HTMLDivElement>(null);const{enquire}=useSite();const max=Math.max(0,featuredSeeds.length-1);useEffect(()=>{const el=viewport.current;const card=el?.querySelector<HTMLElement>('.featured-link');if(!el||!card)return;const gap=parseFloat(getComputedStyle(el.querySelector('.featured-track')!).gap||'0');el.scrollTo({left:index*(card.offsetWidth+gap),behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})},[index]);function move(dir:number){setIndex(i=>dir>0?i>=max?0:i+1:i<=0?max:i-1)}return <section className="section featured-aaramv" aria-labelledby="featured-aaramv-title"><div className="wrap"><div className="featured-head"><div><div className="eyebrow">Featured By AaramV</div><h2 id="featured-aaramv-title">Handpicked listings, ready for a closer look.</h2></div><div className="featured-controls"><button className="circle" onClick={()=>move(-1)} aria-label="Previous featured property"><ChevronLeft size={19}/></button><button className="circle" onClick={()=>move(1)} aria-label="Next featured property"><ChevronRight size={19}/></button></div></div></div><div className="featured-viewport" ref={viewport} aria-live="polite"><div className="featured-track">{featuredSeeds.map((item,i)=>{const p=item.id?properties.find(x=>x.id===item.id):undefined;const href=p?`/properties/${p.id}`:'';const image=p?.image||img(item.image);const locality=p?.locality||item.locality;return <div className={`featured-link ${i===index?'active':Math.abs(i-index)===1?'near':'far'}`} key={item.name} aria-hidden={i!==index}><article className="featured-card"><div className="featured-media"><img src={image} alt={`${item.name} featured property visual`} loading="lazy"/><span>{String(i+1).padStart(2,'0')}</span></div><div className="featured-copy"><div className="featured-meta"><span>{item.developer}</span><span>{p?.status||item.status}</span></div><h3>{item.name}</h3><p>{item.summary}</p><div className="featured-specs"><span><MapPin size={14}/>{locality}</span><span>{p?configurationSummary(p):item.type}</span></div><div className="featured-price">{p?<PropertyPrice p={p}/>:<strong>{item.price}</strong>}{href?<Link href={href} className="circle" aria-label={`View ${item.name}`} tabIndex={i===index?0:-1}><ArrowUpRight size={17}/></Link>:<button className="circle" onClick={()=>enquire(`Featured listing enquiry: ${item.name}`)} aria-label={`Enquire about ${item.name}`} tabIndex={i===index?0:-1}><ArrowUpRight size={17}/></button>}</div></div></article></div>})}</div></div><div className="wrap featured-dots" aria-label="Featured property carousel position">{Array.from({length:max+1}).map((_,i)=><button key={i} className={i===index?'active':''} aria-label={`Show featured property ${i+1}`} aria-pressed={i===index} onClick={()=>setIndex(i)}/>)}</div></section>}
