function DesktopListings(){
const params=useSearchParams();const{saved}=useSite();
const[q,setQ]=useState(params.get('q')||'');const[search,setSearch]=useState(params.get('q')||'');
const[type,setType]=useState(propertyType(params.get('type')||'All'));const[status,setStatus]=useState(params.get('status')||'Any status');
const filterRef=useStickySidebar('top');
const[locality,setLocality]=useState(params.get('locality')||'all');
const bedroomOptions=[...new Set(properties.filter(p=>p.type!=='Plot').flatMap(p=>p.configurations.flatMap(c=>c.bedrooms===null?[]:[c.bedrooms])))].sort((a,b)=>a-b);
const[bhk,setBhk]=useState(params.has('bhk')&&bedroomOptions.includes(Number(params.get('bhk')))?bedroomLabel(Number(params.get('bhk')),'Apartment'):'Any');
const queryNumber=(key:string)=>{const value=params.get(key);return value!==null&&value.trim()!==''&&Number.isFinite(Number(value))&&Number(value)>=0?Number(value):undefined;};
const bounds=budgetBounds(properties);bounds[1]=Math.max(bounds[1],queryNumber('min')??0,queryNumber('budget')??0);
const initialBudget=[queryNumber('min')??bounds[0],queryNumber('budget')??bounds[1]].sort((a,b)=>a-b);
const[budget,setBudget]=useState(initialBudget);const[budgetActive,setBudgetActive]=useState(queryNumber('min')!==undefined||queryNumber('budget')!==undefined);
const[onlySaved,setOnlySaved]=useState(params.get('saved')==='true');const[sort,setSort]=useState('Recommended');const[panel,setPanel]=useState(false);
const results=filterProperties(properties,{query:search,type:type==='All'?undefined:type,status:status==='Any status'?undefined:status,localityId:locality==='all'?undefined:locality,bedrooms:bhk==='Any'?undefined:bhk==='Studio'?0:Number.parseInt(bhk,10),minPriceInr:budgetActive?Math.round(budget[0]*10000000):undefined,maxPriceInr:budgetActive?Math.round(budget[1]*10000000):undefined,savedIds:onlySaved?saved:undefined,sort});
function reset(){setQ('');setSearch('');setType('All');setStatus('Any status');setLocality('all');setBhk('Any');setBudget(bounds);setBudgetActive(false);setOnlySaved(false)}

const filters=<aside className="filter-box" ref={filterRef}><div className="row spread"><h3>Find your fit</h3><button className="reset" onClick={reset}>Reset all</button></div><div className="filter-group"><label>Locality</label><Select value={locality} onValueChange={setLocality}><SelectTrigger aria-label="Filter locality" className="custom-select"><SelectValue/></SelectTrigger><SelectContent position="popper"><SelectItem value="all">All Bengaluru</SelectItem>{localities.map(l=><SelectItem key={l.id} value={l.id}>{l.name}</SelectItem>)}</SelectContent></Select></div><div className="filter-group"><label>Property type</label><RadioGroup value={type} onValueChange={setType} className="filter-radios">{['All',...propertyTypes].map(t=><label key={t} className={type===t?'selected':''}><RadioGroupItem value={t} className="sr-only"/>{t}</label>)}</RadioGroup></div><div className="filter-group"><label>Budget range</label><div className="filter-range"><span>{price(budget[0])}</span><span>{price(budget[1])}</span></div><Slider aria-label="Budget range in crores" min={bounds[0]} max={bounds[1]} step={.01} value={budget} onValueChange={values=>{setBudget(values);setBudgetActive(true)}} minStepsBetweenThumbs={0}/></div><div className="filter-group"><label>Bedrooms</label><RadioGroup value={bhk} onValueChange={setBhk} className="filter-radios">{['Any',...bedroomOptions.map(n=>bedroomLabel(n,'Apartment'))].map(t=><label key={t} className={bhk===t?'selected':''}><RadioGroupItem value={t} className="sr-only"/>{t}</label>)}</RadioGroup></div><div className="filter-group"><label>Project status</label><Drop label="Filter project status" value={status} onChange={setStatus} options={['Any status',...statusOptions]}/></div><div className="filter-group saved-filter"><label className="check-line"><Checkbox checked={onlySaved} onCheckedChange={v=>setOnlySaved(v===true)}/> Saved homes only <Heart size={12}/></label></div></aside>;
return <main className="inner listing-page"><div className="wrap"><Breadcrumb items={[["Properties",'']]}/><div className="inner-head"><div className="eyebrow">A place that feels like you</div><h1>Your Bengaluru. Your home.</h1><p>Explore spaces, compare the details, and find your next beginning.</p></div><form className="listing-search" onSubmit={e=>{e.preventDefault();setSearch(q)}}><div className="search-bar"><div className="search-field"><Search size={18}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search by project, locality or zone" aria-label="Search properties"/></div><button className="btn primary">Search <ArrowRight size={17}/></button></div><button type="button" className="btn outline mobile-filter-button" onClick={()=>setPanel(true)}><SlidersHorizontal size={18}/> Filters</button></form><div className="listing-layout">{filters}<div className="listing-results"><div className="results-top"><span><strong>{results.length}</strong> {results.length===1?'property':'properties'} to explore</span><Drop label="Sort properties" value={sort} onChange={setSort} options={['Recommended','Price: low to high','Price: high to low']}/></div>{(search||type!=='All'||status!=='Any status'||locality!=='all'||bhk!=='Any'||budgetActive||onlySaved)&&<div className="active-filters">{search&&<button onClick={()=>{setSearch('');setQ('')}}>{search}<X size={12}/></button>}{type!=='All'&&<button onClick={()=>setType('All')}>{type}<X size={12}/></button>}{status!=='Any status'&&<button onClick={()=>setStatus('Any status')}>{status}<X size={12}/></button>}{locality!=='all'&&<button onClick={()=>setLocality('all')}>{localities.find(l=>l.id===locality)?.name||locality}<X size={12}/></button>}{bhk!=='Any'&&<button onClick={()=>setBhk('Any')}>{bhk}<X size={12}/></button>}{budgetActive&&<button onClick={()=>{setBudget(bounds);setBudgetActive(false)}}>{price(budget[0])} - {price(budget[1])}<X size={12}/></button>}{onlySaved&&<button onClick={()=>setOnlySaved(false)}>Saved homes<X size={12}/></button>}</div>}{results.length?<div className="property-grid">{results.map(p=><PropertyCard key={p.id} p={p}/>)}</div>:<div className="empty"><Search size={36}/><h3>A fresh search could open doors.</h3><p>{onlySaved?'Save a few homes using the heart icon to see them here.':'Try a different locality, a wider budget or fewer filters.'}</p><button className="btn primary" onClick={reset}>Reset filters <ArrowRight size={16}/></button></div>}<div className="results-bottom">{results.length>0&&<><Check size={15}/> You’re all caught up · {results.length} properties</>}</div></div></div></div><Sheet open={panel} onOpenChange={setPanel}><SheetContent side="left" className="filter-sheet"><SheetTitle className="sr-only">Property filters</SheetTitle><SheetDescription className="sr-only">Narrow the property collection.</SheetDescription>{filters}<button className="btn primary full" style={{marginTop:24}} onClick={()=>setPanel(false)}>Show {results.length} properties <ArrowRight size={16}/></button></SheetContent></Sheet><CTA/></main>}
function PropertyDetail({p}:{p:Property}) {
  const responsive=useResponsiveLayout();
  const formRef=useStickySidebar();
  const [selectedImage,setSelectedImage]=useState<string|null>(null);
  const {saved,toggle,enquire}=useSite();
  const related=p.relatedPropertyIds.length ? p.relatedPropertyIds.flatMap(id=>properties.filter(other=>other.id===id)) : properties.filter(other=>other.id!==p.id).toSorted((a,b)=>Number(b.localityId===p.localityId)-Number(a.localityId===p.localityId)).slice(0,3);
  const sections=[['Overview',true],['Layouts',true],['Amenities',p.amenities.length>0],['Location',true],['FAQs',p.faqs.length>0]] as const;
  const facts=[
    {icon:p.icons.configuration,label:'Configuration',value:configurationSummary(p)},
    {icon:p.icons.area,label:p.primary.areaBasis==='unspecified'?'Area':p.primary.areaBasis.replaceAll('-',' ')+' area',value:formatArea(p.primary.areaSqFt)},
    {icon:p.icons.status,label:'Project status',value:p.status},
    {icon:p.icons.possession,label:'Possession',value:p.possession.label},
  ];
  return <main className="inner property-detail-page"><div className="wrap">
    <Breadcrumb items={[['Properties','/properties'],[p.name,'']]}/>
    <div className="detail-banner"><img src={p.cover.src} alt={p.cover.alt}/><span className="tag">{p.status}</span>{p.cover.caption&&<span className="banner-caption">{p.cover.caption}</span>}<button className="btn white gallery-btn" onClick={()=>setSelectedImage(p.coverImageId)}><Images size={17}/> View gallery · {p.images.length}</button></div>
    <div className="detail-layout"><div className="detail-main">
      <div className="row spread" style={{alignItems:'start'}}><h1>{p.name}</h1><button className={`circle ${saved.includes(p.id)?'saved':''}`} aria-label={saved.includes(p.id)?'Unsave property':'Save property'} aria-pressed={saved.includes(p.id)} onClick={()=>toggle(p.id)}><Heart size={18} fill={saved.includes(p.id)?'currentColor':'none'}/></button></div>
      <div className="detail-location"><DataIcon name={p.icons.location} size={15} label="location"/>{p.locality}, {p.zone}</div>
      {(p.developerName||p.phaseName||p.address||p.postalCode)&&<div className="catalog-meta">{p.developerName&&<p>By {p.developerName}{p.phaseName&&` · ${p.phaseName}`}</p>}{!p.developerName&&p.phaseName&&<p>{p.phaseName}</p>}{(p.address||p.postalCode)&&<p>{[p.address,p.postalCode].filter(Boolean).join(', ')}</p>}</div>}
      <div className="detail-price"><PropertyPrice p={p}/>{p.isDemo&&<small>Illustrative prices</small>}</div>
      <div className="r-responsive-region"><ResponsiveProjectSummary p={p}/></div>
      <div className="detail-facts">{facts.map(fact=><div key={fact.label}><DataIcon name={fact.icon} label={fact.label}/><p>{fact.label}</p><strong>{fact.value}</strong></div>)}</div>
      <nav className="anchor-nav" aria-label="Property sections">{sections.filter(([,visible])=>visible).map(([title])=><a key={title} href={`#${title.toLowerCase()}`}>{title}</a>)}</nav>
      <section className="detail-section" id="overview"><h2>{p.content.overviewTitle}</h2><p>{p.description}</p>{p.possession.date&&<p>Expected possession date: <time dateTime={p.possession.date}>{p.possession.date}</time></p>}
        <div className="highlights">{p.highlights.map((item,i)=><span key={i}><DataIcon name={item.icon} size={15} label={item.title}/><span>{item.title}{item.description&&<small className="catalog-unit-note">{item.description}</small>}</span></span>)}</div>
        {!!p.facts.length&&<div className="detail-facts catalog-facts">{p.facts.map((fact,i)=><div key={i}><DataIcon name={fact.icon} label={fact.label}/><p>{fact.label}</p><strong>{typeof fact.value==='number'?fact.value.toLocaleString('en-IN'):fact.value}{fact.unit&&` ${fact.unit}`}</strong></div>)}</div>}
      </section>
      <section className="detail-section" id="layouts"><h2>{p.content.layoutsTitle}</h2><PropertyLayouts key={p.id} p={p} onImage={setSelectedImage}/>
        {p.content.layoutsNote&&<p className="sample-note" style={{fontSize:12,marginTop:14}}>{p.content.layoutsNote}</p>}<button className="btn outline small" style={{marginTop:18}} onClick={()=>enquire(`Request floor plans: ${p.name}`,p.name)}>Request the floor plans <ArrowUpRight size={15}/></button>
      </section>
      {!!p.amenities.length&&<section className="detail-section" id="amenities"><h2>{p.content.amenitiesTitle}</h2><div className="amenities">{p.amenities.map((item,i)=><div className="amenity" key={i}><DataIcon name={item.icon} size={25} label={item.title}/>{item.title}{item.description&&<small className="catalog-amenity-note">{item.description}</small>}</div>)}</div>{p.content.amenitiesNote&&<p className="sample-note" style={{fontSize:12,marginTop:14}}>{p.content.amenitiesNote}</p>}</section>}
      <section className="detail-section" id="location"><h2>{p.content.locationTitle}</h2><div className="location-panel"><h3>{p.locality}</h3>{p.content.locationDescription&&<p>{p.content.locationDescription}</p>}<PropertyMap p={p}/><Places items={p.nearbyPlaces}/><MapLink record={p}/><Link href={`/localities/${p.localityId}`} className="text-link" style={{marginTop:20}}>Explore {p.locality} <ArrowUpRight size={15}/></Link></div></section>
      {!!p.faqs.length&&<section className="detail-section faq" id="faqs"><h2>{p.content.faqsTitle}</h2>{p.faqs.map((item,i)=><details key={i}><summary>{item.question}</summary><p>{item.answer}</p></details>)}</section>}
    </div><aside className="detail-form" ref={formRef}><h3><span className="mobile-only">Could this be<br/>your next home?</span><span className="desktop-only">Your next home?</span></h3><p><span className="mobile-only">Get the details, ask a question,<br/>or plan a personal site visit.</span><span className="desktop-only">Ask a question or plan a visit.</span></p><LeadForm compact variant="project" project={p.name} context={p.name}/></aside></div>
    {!!related.length&&<section style={{paddingBottom:80}}><div className="section-head"><h2 style={{fontSize:39}}>A few more possibilities.</h2><Link href="/properties" className="text-link">Explore the collection <ArrowUpRight size={16}/></Link></div><div className="property-grid">{related.map(other=><PropertyCard p={other} key={other.id}/>)}</div></section>}
    </div><Gallery key={selectedImage} name={p.name} images={p.images} selectedId={selectedImage} onClose={()=>setSelectedImage(null)}/>{responsive&&<ResponsiveVisitAction p={p} enquire={enquire}/>}</main>;
}
function DesktopLocalities(){const[zone,setZone]=useState('All Bengaluru');return <main className="inner localities-page"><div className="wrap"><Breadcrumb items={[["Localities",'']]}/><section className="city-hero"><div><div className="eyebrow">A city of many beginnings</div><h1><span>Find your kind of </span><em>Bengaluru.</em></h1><p>A neighbourhood shapes your everyday. From established urban addresses to communities with room to grow, get to know the places behind the properties.</p><a href="#neighbourhoods" className="btn primary">Explore neighbourhoods <ArrowRight size={16}/></a></div><div className="city-image"><img src={img('bengaluru-skyline')} alt="Bengaluru skyline photographed by Umang S"/><span>Bengaluru, Karnataka</span></div></section></div><section className="section city-overview"><div className="wrap"><div className="section-head"><div><div className="eyebrow">Understand the city before the address</div><h2>One city. Many ways to live.</h2></div><p>Bengaluru is a collection of distinct micro-markets. A good choice starts with your daily life, not just a city-wide headline.</p></div><div className="three-cols">{[[BriefcaseBusiness,'Follow your everyday','Begin with work, school and the journeys you make most often. The exact route can matter more than the distance.'],[TrainFront,'Read connectivity carefully','Separate operating infrastructure from proposed plans. Check station access, approach roads and travel times yourself.'],[House,'Compare the complete picture','Assess the property, developer, legal documents, ongoing costs and neighbourhood together. Prices vary within every locality.']].map(([Icon,t,d])=>{const I=Icon as typeof House;return <div className="plain-feature" key={String(t)}><I size={27} strokeWidth={1.3}/><h3>{String(t)}</h3><p>{String(d)}</p></div>})}</div></div></section><section className="section" id="neighbourhoods"><div className="wrap"><div className="section-head"><div><div className="eyebrow">Neighbourhood notes</div><h2>Where will your{' '}<span className="heading-break"> </span>next chapter begin?</h2></div><div className="filter-chips" style={{margin:0}}>{['All Bengaluru',...new Set(localities.map(l=>l.zone))].map(z=><button key={z} className={`chip ${zone===z?'selected':''}`} aria-pressed={zone===z} onClick={()=>setZone(z)}>{z}</button>)}</div></div><div className="hotspot-list">{localities.filter(l=>zone==='All Bengaluru'||l.zone===zone).map((l,i)=><Link href={`/localities/${l.slug}`} className="hotspot" key={l.slug}><span>0{i+1}</span><div><h3>{l.name}</h3><p>{l.label}. {l.zone}.</p><div className="hotspot-tags">{l.tags.map(t=><span className="tag" key={t}>{t}</span>)}</div></div><div className="hotspot-image"><img src={img(l.image)} alt={l.cover.alt} loading="lazy"/></div><span className="circle"><ArrowUpRight size={19}/></span></Link>)}</div></div></section><CTA/></main>}
function LocalityDetail({l}:{l:typeof localities[number]}) {
  const projectVisual=properties.find(p=>p.images.some(image=>image.src===l.cover.src));
  const ps=properties.filter(p=>p.localityId===l.id);
  return <main className="inner locality-detail-page"><div className="wrap"><Breadcrumb items={[['Localities','/localities'],[l.name,'']]}/>
    <section className="locality-detail-hero"><img src={l.cover.src} alt={l.cover.alt}/><div><h1>{l.name}.</h1><p>{l.tagline}</p>{projectVisual&&<span className="r-locality-visual-note">Project image: {projectVisual.name}</span>}{l.cover.caption&&<span style={{fontSize:12,color:'#c6d6e1',display:'block',marginTop:15}}>{l.cover.caption}</span>}</div></section>
    <div className="locality-summary"><div><h2>A closer look<span className="heading-break"> </span>at {l.name}.</h2><p>{l.description}</p>{l.considerations.map((item,i)=><p key={i}>{item}</p>)}<p className="catalog-meta">{l.zone} · {l.city}, {l.state}, {l.country}</p><MapLink record={l}/></div><div className="locality-highlights">{l.highlights.map((item,i)=><div key={i}><DataIcon name={item.icon} size={22}/><h3>{item.title}</h3><p>{item.description}</p></div>)}</div></div>
    <LocalityExtras locality={l}/>
    <section className="section rule"><div className="section-head"><h2>Homes in {l.name}.</h2><Link href={`/properties?locality=${encodeURIComponent(l.id)}`} className="text-link">Refine your search <SlidersHorizontal size={16}/></Link></div>{ps.length?<div className="property-grid">{ps.map(p=><PropertyCard key={p.id} p={p}/>)}</div>:<p>No homes are currently listed in this locality.</p>}</section>
  </div><CTA/></main>;
}
function About(){return <main className="inner about-page"><div className="wrap"><Breadcrumb items={[["About us",'']]}/><div className="about-hero"><div className="eyebrow">The people behind your beginning</div><h1>Real estate is about places.<span className="heading-break"> </span>For us, it starts with <em>people.</em></h1><p><span className="mobile-only">Local knowledge. Honest conversations. Thoughtful guidance.<br/>Aaramv is a Bengaluru property partner built around a simple idea: your next home should feel like the right decision.</span><span className="desktop-only">Local knowledge. Honest conversations. Thoughtful guidance.<br/>Your Bengaluru property partner, helping your next home feel right.</span></p></div><div className="about-image"><img src={img('living-room')} alt="Light-filled home interior"/><span>Spaces for life’s next chapter</span></div><section className="section advisor-difference"><AdvisorPartnership/><Stats/></section></div><section className="motto"><div className="wrap"><div className="eyebrow">The belief that guides us</div><blockquote>“The right beginning is more than an address. It’s the confidence to call it home.”</blockquote><p>Aaramv Realty</p></div></section><section className="section"><div className="wrap"><div className="section-head"><div><div className="eyebrow">A personal partnership</div><h2>People you can<span className="heading-break"> </span>move forward with.</h2></div><p>Meet the teams that guide your search, visits, comparisons and handover journey.</p></div><div className="three-cols">{[['Founder & principal advisor','Sets the standard for thoughtful advice and long-term client relationships.'],['Property advisory team','Helps you compare neighbourhoods, shortlist homes and make sense of the details.'],['Client experience team','Coordinates site visits, documentation requests and your journey through handover.']].map(([t,d])=><article className="team-card" key={t}><div className="team-avatar"><Users size={30} strokeWidth={1.2}/></div><h3>{t}</h3><p>{d}</p></article>)}</div></div></section><CTA/></main>}
function Contact(){const{enquire}=useSite();return <main className="inner"><div className="wrap"><Breadcrumb items={[["Contact",'']]}/><div className="contact-layout"><div><div className="eyebrow">A conversation away</div><h1>Let’s find<span className="heading-break"> </span>your beginning.</h1><p>Just starting to explore, or ready to visit?<br/>Tell us where you are in your home-buying journey.</p><div className="contact-options">{[[Phone,'Talk it through','Share your questions and request a personal callback.'],[Compass,'See it for yourself','We’ll help you plan visits to shortlisted homes.'],[MapPin,'Rooted in Bengaluru','Local guidance across the city’s residential neighbourhoods.']].map(([Icon,t,d])=>{const I=Icon as typeof Phone;return <div className="contact-option" key={String(t)}><I size={23} strokeWidth={1.4}/><div><h3>{String(t)}</h3><p>{String(d)}</p></div></div>})}</div><button className="btn outline" style={{marginTop:20}} onClick={()=>enquire('Speak with a property advisor')}>Speak with an advisor <ArrowUpRight size={16}/></button></div><div className="contact-form"><h3>A few details.<br/>A better conversation.</h3><LeadForm extended context="Contact enquiry"/></div></div></div></main>}
const legalContent={terms:[['Using this website','Aaramv Realty provides property discovery, shortlist support, site-visit coordination and advisory assistance for home buyers in Bengaluru. Website content is intended to help you compare options and start a conversation with our team.'],['Property information','Project names, prices, configurations, possession timelines, amenities and availability can change over time. Final purchase terms are governed by the developer’s current offer documents, allotment letter, agreement and applicable registrations.'],['Our role','Aaramv Realty acts as a real estate advisory and channel-partner service. Developer approvals, construction commitments, unit allotment, payments, handover and warranties remain subject to the relevant developer and transaction documents.'],['Enquiries and bookings','Submitting an enquiry helps our team understand your requirement and coordinate the next step. A booking or purchase is created only through the applicable written process with the concerned developer or seller.'],['Buyer diligence','Before making a purchase decision, review the cost sheet, unit plan, legal documents, registration details, payment schedule, cancellation terms and handover conditions with your own professional advisors.'],['Content and contact','Website content, images and brand materials belong to their respective owners and must be used only with permission. For questions, contact Aaramv Realty through the enquiry channels on this website.']],privacy:[['Information we collect','When you submit an enquiry, we may collect your name, phone number, property preference, budget, email address and message so our team can respond to your requirement.'],['How we use information','We use enquiry information to contact you, understand your property needs, suggest relevant projects, coordinate site visits and support your home search.'],['Saved homes','Saved homes are stored in your browser so your shortlist remains available on the same device. You can remove a saved home by tapping the heart icon again.'],['Service providers','Hosting, analytics, communication and customer-management tools may process technical or enquiry information for operating the website and responding to requests.'],['Your choices','You can choose what details to share in an enquiry. You may ask us to update or remove your contact details from our follow-up list.'],['Policy updates','This policy may be updated as Aaramv Realty services, tools and operations evolve. The latest version on this website applies to your use of the site.']]};
function Legal({kind}:{kind:'terms'|'privacy'}){const title=kind==='terms'?'Terms & conditions':'Privacy policy';return <main className="inner"><div className="wrap"><Breadcrumb items={[[title,'']]}/><div className="inner-head"><div className="eyebrow">Clarity in the details</div><h1>{title}.</h1><p>Clear expectations. Thoughtful handling of information.</p></div><div className="legal-layout"><nav className="legal-toc" aria-label="Policy contents">{legalContent[kind].map(([t],i)=><a href={`#legal-${i}`} key={t}>0{i+1} &nbsp; {t}</a>)}</nav><div className="legal-body">{legalContent[kind].map(([t,d],i)=><section id={`legal-${i}`} key={t}><h2>{t}</h2><p>{d}</p></section>)}<Link href="/contact" className="btn outline">Questions? Let’s talk <ArrowUpRight size={16}/></Link></div></div></div></main>}
function Utility({coming=false}:{coming?:boolean}){const[done,setDone]=useState(false);return <main className="inner"><div className="wrap utility-page"><div>{coming?<div className="eyebrow">A little more to look forward to</div>:<div className="utility-number">404</div>}<h1>{coming?<>Good things<span className="heading-break"> </span>are taking shape.</>:<>This isn’t quite<span className="heading-break"> </span>the right address.</>}</h1><p>{coming?'New possibilities. Fresh perspectives. We’re getting the next part of Aaramv ready for you.':'The page you’re looking for may have moved. Let’s get you back to somewhere that feels like home.'}</p>{coming?done?<div className="form-success" role="status"><CheckCircle2 size={27}/><h3>You’re on the list.</h3><p>Thank you. We’ll keep you posted when this section opens.</p></div>:<form className="coming-form" onSubmit={e=>{e.preventDefault();setDone(true)}}><input type="email" required placeholder="Your email address" aria-label="Email for launch notification"/><button className="btn primary">Notify me <ArrowUpRight size={16}/></button></form>:<div className="row" style={{flexWrap:'wrap'}}><Link href="/" className="btn primary">Back to home <ArrowRight size={16}/></Link><Link href="/properties" className="btn outline">Explore properties</Link></div>}{coming&&<Link href="/" className="text-link" style={{marginTop:25}}>Explore Aaramv today <ArrowRight size={16}/></Link>}</div><div className="coming-visual"><img src={img(coming?'apartment-green':'villa')} alt="Residential architecture"/></div></div></main>}
export default function Site(){const path=usePathname();const params=useSearchParams();const{saved,toggle}=useSavedHomes(savedPropertyIds);const[enquiry,setEnquiry]=useState('');const[enquiryProject,setEnquiryProject]=useState('');useSingleLineHeadings(path);function openEnquiry(context:string,project=''){setEnquiryProject(project);setEnquiry(context)}useEffect(()=>{setEnquiry('');if(!window.location.hash&&!window.matchMedia('(max-width: 1199px)').matches)window.scrollTo(0,0)},[path]);let page:ReactNode;const parts=path.split('/').filter(Boolean);if(path==='/')page=<Home/>;else if(path==='/properties')page=<Listings key={params.toString()}/>;else if(parts[0]==='properties'&&parts.length===2){const p=properties.find(p=>p.id===parts[1]);page=p?<PropertyDetail p={p} key={p.id}/>:<Utility/>}else if(path==='/localities')page=<Localities/>;else if(parts[0]==='localities'&&parts.length===2){const l=localities.find(l=>l.slug===parts[1]);page=l?<LocalityDetail l={l}/>:<Utility/>}else if(path==='/about')page=<About/>;else if(path==='/contact')page=<Contact/>;else if(path==='/terms')page=<Legal kind="terms"/>;else if(path==='/privacy')page=<Legal kind="privacy"/>;else if(path==='/coming-soon')page=<Utility coming/>;else page=<Utility/>;return <Context.Provider value={{saved,toggle,enquire:openEnquiry}}><PropertyTools/><a href="#main-content" className="skip-link">Skip to content</a><Header/><div id="main-content">{page}</div><Footer/><Dialog open={!!enquiry} onOpenChange={v=>!v&&setEnquiry('')}><DialogContent className={`dialog-form ${enquiryProject?'project-dialog':'advisor-dialog'}`}><div className="enquiry-dialog-mark" aria-hidden="true"><Phone size={24}/></div><DialogTitle>{enquiryProject?'A visit. A clearer picture.':'Let’s talk about your next chapter.'}</DialogTitle><DialogDescription>{enquiry}</DialogDescription><LeadForm key={`${enquiry}-${enquiryProject}`} context={enquiry} variant={enquiryProject?'project':'header'} project={enquiryProject||undefined}/></DialogContent></Dialog><Toaster position="bottom-center" richColors closeButton toastOptions={{className:'enquiry-toast',duration:6000}}/></Context.Provider>}
